function centerItem(tabContainer,listItem){const tabsNav=tabContainer.querySelector(".tabs-nav"),tabWidth=tabsNav.offsetWidth,scrollLeft=tabsNav.scrollLeft,itemOffsetLeft=listItem.offsetLeft,itemWidth=listItem.offsetWidth,scrollAmount=itemOffsetLeft-scrollLeft-tabWidth/2+itemWidth/2;tabsNav.scrollTo({left:scrollLeft+scrollAmount,behavior:"smooth"})}
document.addEventListener("DOMContentLiteSpeedLoaded",()=>{document.querySelectorAll(".custom-tab-sangvish").forEach((tabContainer)=>{const activeTab=tabContainer.querySelector(".nav li.active");if(activeTab)centerItem(tabContainer,activeTab);tabContainer.querySelectorAll(".nav li").forEach((listItem)=>{listItem.addEventListener("click",function(){centerItem(tabContainer,this)})})})})